                     "query":  "alcalde jesus maria",
                     "title":  "🚨🔥 #POLÍTICA | JESÚS MARÍA 2027 🔥🚨  📊💥 ¡SE MUEVE EL TABLERO POLÍTICO EN JESÚS MARÍA!  La ci...",
                     "source":  "Aguascalientes Denuncia Ciudadana",
                     "published_date":  "2026-05-24T00:13:46",
                     "summary":  "🚨🔥 #POLÍTICA | JESÚS MARÍA 2027 🔥🚨\n\n📊💥 ¡SE MUEVE EL TABLERO POLÍTICO EN JESÚS MARÍA!\n\nLa ciudadanía comienza a mostrar nuevas preferencias rumbo al 2027 y un nombre empieza a sonar con fuerza en diferentes colonias y comunidades: Mayra Esparza 👀🔥\n\nCon respaldo creciente y presencia cada vez más fuerte entre vecinos de Jesús María, Mayra estaría dejando atrás a perfiles que anteriormente dominaban las conversaciones políticas como Daniel Segura, Poncho de Luna y Jorge Barragán. 📉⚠️\n\n😡📉 De acuerdo con comentarios ciudadanos y movimientos en redes sociales, Daniel Segura habría caído hasta los últimos lugares de aprobación, perdiendo fuerza y respaldo entre distintos sectores del municipio.\n\n💣 Vecinos aseguran:\n🗣️ “La gente quiere nuevos perfiles”\n🗣️ “Ya están cansados de los mismos”\n🗣️ “Se viene una sacudida política en Jesús María”\n\n🔥 Mientras algunos actores políticos parecen estancarse, otros comienzan a crecer rápidamente con el apoyo ciudadano.\n\n👀 El ambiente rumbo al 2027 ya comenzó…\nY en Jesús María la pelea política apenas empieza. 🚨🗳️\n\n😡🔥📉⚠️💣👊🗳️🚨",
