                     "published_date":  "2026-06-19T10:02:20",
                     "summary":  "🌧️ En Jesús María, los cuerpos de seguridad, Protección Civil y las distintas áreas operativas del municipio se mantienen en alerta permanente para atender de manera oportuna cualquier emergencia o situación de riesgo derivada de las lluvias.\n\nTu participación también es fundamental: evita tirar basura en la vía pública, mantén limpios los frentes de tu hogar y reporta alcantarillas obstruidas. Con pequeñas acciones podemos reducir riesgos y evitar encharcamientos.\n\nLa prevención la construimos entre todos.\n\n#JesúsMaría #CiudadDeVanguardia",
